// axi4_lite_regs_tb.v
// Self-checking testbench for axi4_lite_regs.
// Inputs are driven after the falling edge; handshakes are sampled before the
// rising edge. Every failed check reports with $error; passes are counted.

`define CHK(c, m) begin if (c) passed = passed + 1; else begin failed = failed + 1; $error("FAIL: %0s (time %0t)", m, $time); end end

module axi4_lite_regs_tb;

    reg         aclk    = 1'b0;
    reg         aresetn = 1'b0;

    reg  [3:0]  awaddr  = 4'h0;
    reg         awvalid = 1'b0;
    reg  [31:0] wdata   = 32'h0;
    reg  [3:0]  wstrb   = 4'h0;
    reg         wvalid  = 1'b0;
    reg         bready  = 1'b0;
    reg  [3:0]  araddr  = 4'h0;
    reg         arvalid = 1'b0;
    reg         rready  = 1'b0;

    wire        awready;
    wire        wready;
    wire [1:0]  bresp;
    wire        bvalid;
    wire        arready;
    wire [31:0] rdata;
    wire [1:0]  rresp;
    wire        rvalid;

    integer passed = 0;
    integer failed = 0;
    reg [8*64-1:0] nonce = 512'd0;

    reg [31:0] model [0:3];

    always #5 aclk = ~aclk;

    axi4_lite_regs #(
        .ADDR_WIDTH(4),
        .DATA_WIDTH(32)
    ) dut (
        .aclk           (aclk),
        .aresetn        (aresetn),
        .s_axil_awaddr  (awaddr),
        .s_axil_awvalid (awvalid),
        .s_axil_awready (awready),
        .s_axil_wdata   (wdata),
        .s_axil_wstrb   (wstrb),
        .s_axil_wvalid  (wvalid),
        .s_axil_wready  (wready),
        .s_axil_bresp   (bresp),
        .s_axil_bvalid  (bvalid),
        .s_axil_bready  (bready),
        .s_axil_araddr  (araddr),
        .s_axil_arvalid (arvalid),
        .s_axil_arready (arready),
        .s_axil_rdata   (rdata),
        .s_axil_rresp   (rresp),
        .s_axil_rvalid  (rvalid),
        .s_axil_rready  (rready)
    );

    // ------------------------------------------------------------------
    // Reference model helpers
    // ------------------------------------------------------------------
    function [31:0] strb_mask(input [3:0] s);
        begin
            strb_mask = {{8{s[3]}}, {8{s[2]}}, {8{s[1]}}, {8{s[0]}}};
        end
    endfunction

    function is_mapped(input [3:0] a);
        begin
            is_mapped = (a[1:0] == 2'b00);
        end
    endfunction

    task clear_model;
        begin
            model[0] = 32'h0;
            model[1] = 32'h0;
            model[2] = 32'h0;
            model[3] = 32'h0;
        end
    endtask

    // ------------------------------------------------------------------
    // Transaction engine: an optional write and an optional read, run
    // cycle by cycle with independent per-channel delays.
    // aw_dly / w_dly / ar_dly: cycles before VALID is raised.
    // b_dly / r_dly: 0 = READY high from the start (before VALID);
    //                n = READY held low for n cycles of VALID.
    // ------------------------------------------------------------------
    integer    cyc;
    integer    wr_done_cyc;
    integer    b_seen_cyc;
    integer    ar_done_cyc;
    integer    r_seen_cyc;
    integer    b_wait;
    integer    r_wait;
    integer    lat;
    reg        aw_done;
    reg        w_done;
    reg        b_done;
    reg        ar_done;
    reg        r_done;
    reg        aw_fire;
    reg        w_fire;
    reg        b_fire;
    reg        ar_fire;
    reg        r_fire;
    reg        b_stall;
    reg        r_stall;
    reg [1:0]  exp_bresp;
    reg [1:0]  exp_rresp;
    reg [31:0] exp_rdata;

    task xact(input wr_en, input [3:0] wa, input [31:0] wd, input [3:0] ws,
              input integer aw_dly, input integer w_dly, input integer b_dly,
              input rd_en, input [3:0] ra,
              input integer ar_dly, input integer r_dly);
        begin
            aw_done     = !wr_en;
            w_done      = !wr_en;
            b_done      = !wr_en;
            ar_done     = !rd_en;
            r_done      = !rd_en;
            wr_done_cyc = -1;
            b_seen_cyc  = -1;
            ar_done_cyc = -1;
            r_seen_cyc  = -1;
            b_wait      = 0;
            r_wait      = 0;
            b_stall     = 1'b0;
            r_stall     = 1'b0;
            exp_bresp   = is_mapped(wa) ? 2'b00 : 2'b10;
            exp_rresp   = 2'b00;
            exp_rdata   = 32'h0;
            cyc         = 0;
            while (!(b_done && r_done) && (cyc < 64)) begin
                @(negedge aclk);
                if (wr_en) begin
                    awaddr  = wa;
                    wdata   = wd;
                    wstrb   = ws;
                    awvalid = !aw_done && (cyc >= aw_dly);
                    wvalid  = !w_done && (cyc >= w_dly);
                    bready  = !b_done && ((b_dly == 0) || (bvalid && (b_wait >= b_dly)));
                end
                if (rd_en) begin
                    araddr  = ra;
                    arvalid = !ar_done && (cyc >= ar_dly);
                    rready  = !r_done && ((r_dly == 0) || (rvalid && (r_wait >= r_dly)));
                end
                #1;

                // ---- checks on the state the previous edge left ----
                if (cyc == 0) begin
                    if (wr_en) `CHK(awready && wready, "AWREADY and WREADY high at the start of a write (B2B)");
                    if (rd_en) `CHK(arready, "ARREADY high at the start of a read (B2B)");
                end

                if (wr_en && !b_done) begin
                    if (bvalid) begin
                        `CHK(wr_done_cyc >= 0, "BVALID only after both AW and W were accepted");
                        `CHK(!awready && !wready, "AWREADY and WREADY low while B is pending");
                        if (b_seen_cyc < 0) begin
                            b_seen_cyc = cyc;
                            lat = cyc - wr_done_cyc;
                            `CHK((lat >= 1) && (lat <= 2), "write latency within the 2-cycle bound");
                            `CHK(lat == 1, "write latency is 1 cycle");
                        end
                        `CHK(bresp == exp_bresp, "BRESP matches the address policy and holds while stalled");
                    end else begin
                        `CHK(!b_stall, "BVALID held until BREADY");
                        if (aw_done && !w_done) `CHK(!awready, "AWREADY low while AW is held");
                        if (w_done && !aw_done) `CHK(!wready, "WREADY low while W is held");
                    end
                end
                if (!wr_en) `CHK(!bvalid, "no B response without a write");

                if (rd_en && !r_done) begin
                    if (rvalid) begin
                        `CHK(ar_done_cyc >= 0, "RVALID only after AR was accepted");
                        `CHK(!arready, "ARREADY low while R is pending");
                        if (r_seen_cyc < 0) begin
                            r_seen_cyc = cyc;
                            lat = cyc - ar_done_cyc;
                            `CHK((lat >= 1) && (lat <= 2), "read latency within the 2-cycle bound");
                            `CHK(lat == 1, "read latency is 1 cycle");
                        end
                        `CHK(rresp == exp_rresp, "RRESP matches the address policy and holds while stalled");
                        `CHK(rdata == exp_rdata, "RDATA matches the model and holds while stalled");
                    end else begin
                        `CHK(!r_stall, "RVALID held until RREADY");
                    end
                end
                if (!rd_en) `CHK(!rvalid, "no R response without a read");

                // ---- what the coming edge will do ----
                b_stall = bvalid && !bready;
                r_stall = rvalid && !rready;
                if (b_stall) b_wait = b_wait + 1;
                if (r_stall) r_wait = r_wait + 1;

                aw_fire = awvalid && awready;
                w_fire  = wvalid && wready;
                b_fire  = bvalid && bready;
                ar_fire = arvalid && arready;
                r_fire  = rvalid && rready;

                // Read samples the registers before this edge's write.
                if (ar_fire) begin
                    ar_done     = 1'b1;
                    ar_done_cyc = cyc;
                    exp_rresp   = is_mapped(ra) ? 2'b00 : 2'b10;
                    exp_rdata   = is_mapped(ra) ? model[ra[3:2]] : 32'h0;
                end
                if (aw_fire) aw_done = 1'b1;
                if (w_fire)  w_done  = 1'b1;
                if (wr_en && (wr_done_cyc < 0) && aw_done && w_done) begin
                    wr_done_cyc = cyc;
                    if (is_mapped(wa)) begin
                        model[wa[3:2]] = (model[wa[3:2]] & ~strb_mask(ws)) | (wd & strb_mask(ws));
                    end
                end
                if (b_fire) b_done = 1'b1;
                if (r_fire) r_done = 1'b1;
                cyc = cyc + 1;
            end
            `CHK(b_done && r_done, "transaction completed before the timeout");
        end
    endtask

    task write_op(input [3:0] a, input [31:0] d, input [3:0] s,
                  input integer awd, input integer wdl, input integer bd);
        begin
            xact(1'b1, a, d, s, awd, wdl, bd, 1'b0, 4'h0, 0, 0);
        end
    endtask

    task read_op(input [3:0] a, input integer ard, input integer rdl);
        begin
            xact(1'b0, 4'h0, 32'h0, 4'h0, 0, 0, 0, 1'b1, a, ard, rdl);
        end
    endtask

    task read_all;
        begin
            read_op(4'h0, 0, 0);
            read_op(4'h4, 0, 0);
            read_op(4'h8, 0, 0);
            read_op(4'hC, 0, 0);
        end
    endtask

    // ------------------------------------------------------------------
    // Test sequence
    // ------------------------------------------------------------------
    initial begin : main_seq
        integer    got;
        integer    seed;
        integer    iter;
        reg [31:0] r;
        reg [31:0] r2;
        reg        we;
        reg        re;
        reg [3:0]  wa_r;
        reg [3:0]  ra_r;

        got = $value$plusargs("nirmaan_nonce=%s", nonce);
        clear_model;

        // ---- T0: reset ----
        aresetn = 1'b0;
        repeat (3) @(posedge aclk);
        @(negedge aclk);
        #1;
        `CHK(!bvalid && !rvalid, "BVALID and RVALID low during reset");
        aresetn = 1'b1;
        @(negedge aclk);
        #1;
        `CHK(awready && wready && arready, "AWREADY WREADY ARREADY high after reset");
        `CHK(!bvalid && !rvalid, "no response after reset");

        // ---- T1: reset values ----
        read_all;

        // ---- T2: write then read every register (AW and W together) ----
        write_op(4'h0, 32'h1111_1111, 4'hF, 0, 0, 0);
        write_op(4'h4, 32'h2222_2222, 4'hF, 0, 0, 0);
        write_op(4'h8, 32'h3333_3333, 4'hF, 0, 0, 0);
        write_op(4'hC, 32'h4444_4444, 4'hF, 0, 0, 0);
        read_all;

        // ---- T3: AW/W ordering ----
        write_op(4'h0, 32'hA5A5_0F0F, 4'hF, 0, 3, 0);   // AW before W, gap
        read_op(4'h0, 0, 0);
        write_op(4'h4, 32'h5A5A_F0F0, 4'hF, 4, 0, 0);   // W before AW, gap
        read_op(4'h4, 0, 0);
        write_op(4'h8, 32'hDEAD_BEEF, 4'hF, 2, 2, 0);   // together after a gap
        read_op(4'h8, 0, 0);
        write_op(4'hC, 32'hCAFE_F00D, 4'hF, 0, 1, 0);   // AW then W next cycle
        read_op(4'hC, 0, 0);
        write_op(4'hC, 32'h0BAD_C0DE, 4'hF, 1, 0, 0);   // W then AW next cycle
        read_op(4'hC, 0, 0);

        // ---- T4: byte strobes ----
        write_op(4'h0, 32'h1234_5678, 4'h1, 0, 0, 0);
        read_op(4'h0, 0, 0);
        write_op(4'h0, 32'h9ABC_DEF0, 4'h6, 0, 0, 0);
        read_op(4'h0, 0, 0);
        write_op(4'h0, 32'h7700_0000, 4'h8, 0, 0, 0);
        read_op(4'h0, 0, 0);
        write_op(4'h8, 32'h1122_3344, 4'hA, 2, 0, 0);
        read_op(4'h8, 0, 0);
        write_op(4'hC, 32'hFFFF_FFFF, 4'h0, 0, 0, 0);   // no strobe: no change, OKAY
        read_all;

        // ---- T5: B and R backpressure ----
        write_op(4'h4, 32'h0BAD_F00D, 4'hF, 0, 0, 5);
        read_op(4'h4, 0, 6);
        write_op(4'h8, 32'hFACE_B00C, 4'hC, 2, 0, 3);
        read_op(4'h8, 2, 4);
        write_op(4'h0, 32'h0000_0001, 4'hF, 0, 3, 1);
        read_op(4'h0, 1, 1);

        // ---- T6: back-to-back transactions ----
        write_op(4'h0, 32'h0101_0101, 4'hF, 0, 0, 0);
        write_op(4'h4, 32'h0202_0202, 4'hF, 0, 0, 0);
        write_op(4'h8, 32'h0303_0303, 4'hF, 0, 0, 0);
        write_op(4'hC, 32'h0404_0404, 4'hF, 0, 0, 0);
        write_op(4'h0, 32'h0505_0505, 4'h3, 0, 0, 0);
        read_op(4'h0, 0, 0);
        read_op(4'h4, 0, 0);
        read_op(4'h8, 0, 0);
        read_op(4'hC, 0, 0);
        read_op(4'h0, 0, 0);

        // ---- T7: SLVERR policy ----
        write_op(4'h5, 32'hFFFF_FFFF, 4'hF, 0, 0, 0);
        write_op(4'hE, 32'hEEEE_EEEE, 4'hF, 1, 0, 2);
        write_op(4'h3, 32'h3333_3333, 4'h0, 0, 0, 0);
        write_op(4'h1, 32'h1111_1111, 4'hF, 0, 2, 0);
        read_op(4'h2, 0, 0);
        read_op(4'hF, 0, 0);
        read_op(4'h9, 0, 3);
        read_op(4'h6, 2, 0);
        read_all;

        // ---- T8: read and write on the same clock ----
        xact(1'b1, 4'h4, 32'h7777_8888, 4'hF, 0, 0, 0, 1'b1, 4'h4, 0, 0);   // same register: old value
        read_op(4'h4, 0, 0);
        xact(1'b1, 4'h0, 32'h1357_9BDF, 4'hF, 2, 0, 3, 1'b1, 4'hC, 0, 2);
        xact(1'b1, 4'h8, 32'h2468_ACE0, 4'hF, 0, 0, 0, 1'b1, 4'h8, 1, 0);   // read one cycle after write
        xact(1'b1, 4'hD, 32'hDDDD_DDDD, 4'hF, 0, 0, 2, 1'b1, 4'h7, 0, 2);   // both unmapped
        xact(1'b1, 4'hC, 32'h0F0F_F0F0, 4'h5, 0, 0, 4, 1'b1, 4'h0, 0, 4);
        read_all;

        // ---- T9: seeded random traffic ----
        seed = 1;
        for (iter = 0; iter < 200; iter = iter + 1) begin
            r  = $random(seed);
            r2 = $random(seed);
            we = r[0];
            re = r[1];
            if (!we && !re) we = 1'b1;
            wa_r = r[28] ? {r[5:4], 2'b00} : r[5:2];
            ra_r = r[29] ? {r[13:12], 2'b00} : r[15:12];
            xact(we, wa_r, r2, r[11:8],
                 {30'd0, r[27:26]}, {30'd0, r[25:24]}, {29'd0, r[18:16]},
                 re, ra_r,
                 {30'd0, r[23:22]}, {29'd0, r[21:19]});
        end
        read_all;

        // ---- T10a: reset drops a half-accepted write ----
        @(negedge aclk);
        awaddr  = 4'h4;
        wdata   = 32'hFFFF_FFFF;
        wstrb   = 4'hF;
        awvalid = 1'b1;
        wvalid  = 1'b0;
        bready  = 1'b0;
        #1;
        `CHK(awready, "AWREADY high before the lone AW");
        @(negedge aclk);
        awvalid = 1'b0;
        #1;
        `CHK(!awready && wready && !bvalid, "lone AW is held and no B is issued");
        aresetn = 1'b0;
        @(negedge aclk);
        #1;
        `CHK(awready && wready && arready && !bvalid && !rvalid, "reset drops the held AW");
        aresetn = 1'b1;
        clear_model;
        read_all;
        write_op(4'h8, 32'h0102_0304, 4'hF, 3, 0, 0);   // W first: must not pair with the dropped AW
        read_op(4'h4, 0, 0);
        read_op(4'h8, 0, 0);

        // ---- T10b: reset clears pending B and R ----
        @(negedge aclk);
        awaddr  = 4'hC;
        wdata   = 32'h89AB_CDEF;
        wstrb   = 4'hF;
        awvalid = 1'b1;
        wvalid  = 1'b1;
        bready  = 1'b0;
        araddr  = 4'h8;
        arvalid = 1'b1;
        rready  = 1'b0;
        #1;
        `CHK(awready && wready && arready, "AW W and AR accepted together");
        @(negedge aclk);
        awvalid = 1'b0;
        wvalid  = 1'b0;
        arvalid = 1'b0;
        #1;
        `CHK(bvalid && (bresp == 2'b00), "B pending with OKAY before reset");
        `CHK(rvalid && (rresp == 2'b00) && (rdata == 32'h0102_0304), "R pending with the register value before reset");
        aresetn = 1'b0;
        @(negedge aclk);
        #1;
        `CHK(!bvalid && !rvalid, "reset clears pending B and R");
        `CHK(awready && wready && arready, "READY high during reset");
        aresetn = 1'b1;
        clear_model;
        read_all;

        // ---- final write/read of every register after reset ----
        write_op(4'h0, 32'hC001_0000, 4'hF, 0, 0, 1);
        write_op(4'h4, 32'hC001_0004, 4'hF, 1, 0, 0);
        write_op(4'h8, 32'hC001_0008, 4'hF, 0, 1, 2);
        write_op(4'hC, 32'hC001_000C, 4'hF, 0, 0, 0);
        read_all;

        $display("NIRMAAN-SIM %0s %0d passed, %0d failed", nonce, passed, failed);
        $finish;
    end

    // Watchdog: a hung run still ends with a failing verdict.
    initial begin : watchdog
        #2000000;
        $error("FAIL: watchdog timeout");
        $display("NIRMAAN-SIM %0s %0d passed, %0d failed", nonce, passed, failed + 1);
        $finish;
    end

endmodule

`undef CHK
